package com.team.student_calendar.repository.jdbc;import com.team.student_calendar.repository.impl.BookJdbcRepository;import lombok.RequiredArgsConstructor;import org.springframework.context.annotation.Profile;import org.springframework.jdbc.core.JdbcTemplate;import org.springframework.stereotype.Repository;@Profile("postgres")@Repository("bookPostgresRepository")@RequiredArgsConstructorpublic class BookPostgresRepository implements BookJdbcRepository {    private static final String INSERT_SQL = """            INSERT INTO student_calendar.book            (title, author, publisher, category, "level", difficulty, book_no, image_url)            VALUES (?, ?, ?, ?, ?, ?, ?, ?)            ON CONFLICT (book_no) DO NOTHING            """;    private final JdbcTemplate jdbcTemplate;    @Override    public JdbcTemplate jdbcTemplate() {        return jdbcTemplate;    }    @Override    public String insertSql() {        return INSERT_SQL;    }}